// Original conceptual interview examples. These are explanations, not executed programs.
// Sources are the language/platform owners; deployment-specific limits remain separate.
export const INTERVIEW_LESSON_SOURCES = {
  python: [['Python tutorial', 'https://docs.python.org/3/tutorial/'], ['asyncio tasks and cancellation', 'https://docs.python.org/3/library/asyncio-task.html']],
  javascript: [['JavaScript execution model', 'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Execution_model'], ['ECMAScript specification', 'https://tc39.es/ecma262/']],
  aws: [['AWS Well-Architected reliability', 'https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html'], ['AWS service documentation', 'https://docs.aws.amazon.com/']],
  react: [['React effects', 'https://react.dev/learn/synchronizing-with-effects'], ['React state ownership', 'https://react.dev/learn/sharing-state-between-components']],
  nodejs: [['Node.js event loop', 'https://nodejs.org/en/learn/asynchronous-work/event-loop-timers-and-nexttick'], ['Node.js streams', 'https://nodejs.org/api/stream.html']],
  go: [['Go concurrency', 'https://go.dev/doc/effective_go#concurrency'], ['Go context', 'https://pkg.go.dev/context']],
  rust: [['Rust ownership', 'https://doc.rust-lang.org/book/ch04-01-what-is-ownership.html'], ['Rust references and borrowing', 'https://doc.rust-lang.org/book/ch04-02-references-and-borrowing.html']],
  docker: [['Docker build practices', 'https://docs.docker.com/build/building/best-practices/'], ['Dockerfile reference', 'https://docs.docker.com/reference/dockerfile/']],
  mongodb: [['MongoDB data modeling', 'https://www.mongodb.com/docs/manual/data-modeling/'], ['MongoDB indexes', 'https://www.mongodb.com/docs/manual/indexes/']],
};

function lesson(question, answer, example, tradeOff, verification, followUp, followUpAnswer) {
  return { question, answer, example, tradeOff, verification, followUp: { question: followUp, answer: followUpAnswer } };
}

export const PUBLIC_INTERVIEW_LESSONS = {
  python: [
    lesson('List versus tuple?', 'A list is a mutable sequence; a tuple fixes the sequence of references. I use a list for items that are added or removed, and a tuple for a fixed record-like result. Neither choice freezes mutable objects inside it, and a tuple is hashable only when all its elements are hashable.', 'A tuple containing a list still permits that inner list to change. A tuple of two integers can be a dictionary key.', 'Immutability of the outer container is different from deep immutability; copying the container alone does not isolate nested state.', 'Try mutation, dictionary-key use, and a nested mutable element before choosing the API contract.', 'Does tuple always use less memory?', 'That is implementation- and shape-dependent. Measure the actual Python runtime; semantics should drive the initial choice.'),
    lesson('What is a generator?', 'A generator produces an iterator that suspends at yield and resumes on the next request. It lets me process a stream without materializing every result. Its state stays alive between requests; it is not a reusable collection and does not make a blocking operation asynchronous.', 'A log reader can yield one matching line at a time instead of building a million-element list.', 'Lazy consumption reduces retained results, but a slow consumer can keep an open file or other resource alive.', 'Consume a small iterator twice, interrupt it early, and verify resource cleanup with a context manager.', 'When is a list better?', 'When callers need repeated traversal, indexing, or a stable snapshot and the retained size is acceptable.'),
    lesson('How does async Python help?', 'An asyncio task can suspend while awaiting non-blocking I/O so the event loop can run other tasks. This is concurrency, not a promise of CPU parallelism. I bound the number of in-flight requests and propagate cancellation; putting a blocking library call inside async def still blocks the event-loop thread.', 'Two independent network waits can overlap, while a CPU-heavy image transform should run in an appropriately bounded worker.', 'More tasks can overload the same database or connection pool, even when event-loop utilization looks low.', 'Test delayed I/O, blocking calls, timeout and cancellation; measure loop lag and downstream concurrency.', 'Does await start a coroutine automatically in parallel?', 'Awaiting directly waits for that coroutine. Explicit task creation or a task group is needed to schedule independent concurrent work.'),
    lesson('How do you handle Python service errors?', 'I validate requests at the boundary, represent expected business failures explicitly, and let unexpected failures reach a centralized safe error handler. Resources close through context managers or finally. Dependency calls have deadlines; a timeout records uncertainty rather than proving that a remote write failed.', 'A duplicate payment request reuses its operation key after a timeout instead of creating a second charge.', 'Catching every Exception and returning success hides defects. Returning internal exception text can expose implementation details or private input.', 'Inject validation failures, dependency timeouts and cleanup errors; assert response status and sanitized logs.', 'Should I retry every exception?', 'No. Retry only classified transient failures when repeating the operation is safe and a finite time/attempt budget remains.'),
    lesson('How do you improve slow Python code?', 'I profile a representative workload and separate CPU, I/O, allocation and lock waiting before changing it. I first remove repeated work or choose a better algorithm, then consider batching or bounded concurrency. I compare successful throughput and tail latency, not only one fast local execution.', 'Replacing repeated linear membership checks with a set can reduce expected lookup work, at the cost of retaining the set.', 'An optimization can increase memory, startup cost or stale cached results. CPU-bound Python behavior also depends on interpreter build and native extensions.', 'Record baseline input size, runtime and p95 latency, then rerun the same workload and correctness tests.', 'Should I add threads first?', 'Only if the measured waiting/parallelism contract benefits. Extra threads can add contention or merely queue work elsewhere.'),
    lesson('What is the difference between is and ==?', 'is checks object identity; == invokes equality semantics. I use is None for the singleton absence marker and == to compare values. Interning of some strings or integers is an implementation optimization, not a valid reason to compare independently created values by identity.', 'Two separately created equal lists compare equal with == but are not the same object.', 'Custom equality may execute code or reject unsupported operands, so equality should have a documented domain.', 'Construct equal distinct objects and unequal objects; test identity separately from equality.', 'Why not use is for numbers?', 'Equal numeric values need not be represented by the same object, especially outside implementation-specific caches.'),
    lesson('Why are mutable default arguments dangerous?', 'Default argument expressions are evaluated when the function definition executes, not afresh for every call. A list default therefore persists across calls. For per-call state I accept None or a private sentinel and create the container inside the function.', 'A function with items=[] that appends a value will share the accumulated list across calls that omit items.', 'Shared defaults can be intentional caches, but then ownership, bounds and concurrency must be explicit rather than accidental.', 'Call the function twice without arguments and once with an explicit list; verify that independent calls do not share state.', 'What if None is a meaningful argument?', 'Use a unique sentinel object so omitted input can be distinguished from an explicit None.'),
    lesson('What does a context manager guarantee?', 'A context manager defines entry and exit behavior around a with block. It centralizes cleanup when the block returns normally or raises. I still define what happens when acquisition or cleanup itself fails; a with statement cannot guarantee cleanup after every process crash or external kill.', 'Opening a file with with closes the file when parsing raises an ordinary exception.', 'A context manager may suppress exceptions if its exit method says so; suppression must be intentional and visible.', 'Test normal return, body failure, acquisition failure and exit failure independently.', 'Is finally equivalent?', 'Both can arrange cleanup, but a context manager packages the resource protocol for consistent reuse.'),
    lesson('Shallow copy versus deep copy?', 'A shallow copy creates a new outer container but shares referenced elements. A deep copy recursively copies supported objects while tracking relationships. I copy to enforce ownership, not reflexively: external resources and domain identity often should not be duplicated.', 'Copying a list of lists with list.copy leaves the inner lists shared; changing an inner item is visible through both outer lists.', 'Deep copying can be expensive and may have surprising behavior for custom objects or resource handles.', 'Mutate both an outer entry and a nested element, and assert which changes are allowed to cross the boundary.', 'Does assignment copy a list?', 'No. Assignment binds another name to the same object; it does not create a container copy.'),
    lesson('How do dictionaries and sets support lookup?', 'Dictionaries associate hashable keys with values; sets track hashable members. Hashing narrows candidates and equality resolves collisions. Expected lookup is constant time for ordinary workloads, but collisions, expensive equality and adversarial input can change the cost.', 'Counting repeated user IDs in a dictionary avoids rescanning all prior IDs for every event.', 'The hash/equality contract and memory overhead matter; a mutable equality-relevant key is unsafe.', 'Test equal distinct keys, collisions and realistic retained size instead of assuming all lookup costs are identical.', 'Can a list be a dictionary key?', 'A normal list is mutable and unhashable. A tuple works only if each component is hashable.'),
    lesson('What does a decorator do?', 'A decorator receives a function or class and returns the object bound to that definition name. A wrapper can add tracing or validation while delegating the original operation. I preserve metadata with functools.wraps and keep exception, async and cancellation behavior compatible with the wrapped callable.', 'A timing decorator records elapsed time in finally so failures are measured too, without swallowing them.', 'Stacking decorators changes their effective order, and a synchronous wrapper can break an async callable contract.', 'Verify return values, raised errors, metadata, and behavior with multiple decorator orders.', 'Is a decorator executed on each call?', 'The decoration expression runs when the definition executes; a returned wrapper runs on later calls.'),
    lesson('How do you choose an exception type?', 'I use a specific built-in or domain exception that describes what the caller can recover from. I preserve the original cause when translating infrastructure errors. Error messages help diagnosis but should not become a protocol parsed by callers.', 'A request parser raises a validation error for malformed input, while an unavailable dependency follows a separate retryable-failure path.', 'Too many exception types burden callers; one generic exception erases useful recovery distinctions.', 'Assert exception types and causal chains, then separately verify user-facing error mapping.', 'Should an error message contain the full request?', 'No. Include safe identifiers and context, and avoid secrets or private payload fields.'),
    lesson('What are type hints used for?', 'Type hints describe expected types to readers and static analysis tools; ordinary annotations do not automatically validate runtime input. I use them alongside tests and boundary validation. A well-typed internal function can still receive untrusted JSON that violates its assumptions.', 'An annotated integer duration still needs runtime checks for type, range and units when it comes from an HTTP request.', 'Detailed types improve tooling but can become harder to maintain than a small explicit data model.', 'Run the selected type checker and test invalid runtime input independently.', 'Does Optional mean the argument may be omitted?', 'It means the value may be None. Omission is controlled separately by whether the parameter has a default.'),
    lesson('How do you bound concurrent requests?', 'I place an explicit limit around active dependency work and also bound waiting/admitted work. A semaphore limits holders, not the number of tasks already allocated while waiting. Each task needs an owner, cancellation path and deadline.', 'A batch of 10,000 URLs can be fed through a bounded worker queue instead of creating 10,000 waiting tasks at once.', 'A lower limit protects the dependency but can increase queue delay; rejecting overload may be safer than retaining it indefinitely.', 'Measure active calls, queued items and oldest age under a slow dependency and cancellation.', 'Can a connection pool be the only limit?', 'Its wait queue and timeout behavior must be checked; it may merely move an unbounded backlog into the pool.'),
    lesson('What happens when an asyncio task is cancelled?', 'Cancellation requests interruption at an await point; it is not proof that a remote side effect was undone. I use finally for local cleanup, propagate cancellation after cleanup, and give related tasks a shared lifetime rather than leaving orphaned work.', 'Cancelling a caller waiting for payment status stops local waiting but still requires reconciling the payment operation key.', 'Suppressing cancellation can prevent timely shutdown, while immediate process exit may leave external work unresolved.', 'Cancel during acquisition and during I/O; verify cleanup and that child tasks do not outlive their owner.', 'Should cleanup swallow cancellation?', 'Usually not. Perform required bounded cleanup and then let the cancellation propagate.'),
    lesson('How should Python code query a database safely?', 'I bind data values using the driver parameter API instead of composing SQL from input. I keep transactions short, close cursors/connections reliably and set acquisition/query budgets. Identifiers such as sort columns need an allowlist because value parameters do not stand in for SQL syntax.', 'A requested sort field is mapped to a known column name; the customer ID remains a bound value.', 'ORM convenience can hide N+1 queries or overly broad transactions; inspect emitted SQL and query counts.', 'Test injection-shaped values, empty results, rollback and pool exhaustion on the actual driver/database pair.', 'Are f-strings safe after validation?', 'Use parameter binding for values even after validation; validation and SQL/data separation solve different problems.'),
    lesson('How do you process a large file safely?', 'I stream records with an explicit encoding and close the input deterministically. I bound record size, retained batches and any downstream work. Streaming the file does not help if the consumer accumulates every parsed result in a list.', 'A CSV importer can validate and write batches of 500 rows while retaining only one bounded batch.', 'Batch size trades memory and transaction duration against per-row overhead; retries also need stable record identity.', 'Test empty input, malformed records, unusually long fields and a failure halfway through a batch.', 'Can CSV be parsed by splitting on commas?', 'Not generally. Quoted fields can contain delimiters and newlines, so use a CSV parser with a defined dialect.'),
    lesson('What makes a useful Python test double?', 'A test double replaces an external boundary with a controlled collaborator. I keep pure rules in ordinary tests and reserve integration tests for real driver, serialization and transaction contracts. A mock that repeats the implementation can pass while the user-visible behavior is wrong.', 'A fake clock makes expiry tests deterministic; a database integration test verifies unique-key conflict behavior.', 'Doubles are fast but can drift from production behavior; contract tests and a small realistic integration suite reduce that risk.', 'Assert outcomes for success, failure and boundary cases rather than only that a private method was called.', 'Should every dependency be mocked?', 'No. Mock expensive or nondeterministic boundaries when useful, not simple value objects or the behavior under test.'),
    lesson('How can a Python service leak memory?', 'Objects remain retained while reachable from long-lived roots even when the application no longer needs them. I compare post-collection retained memory under stable work, then inspect retaining structures such as caches, task lists and callbacks. High allocation alone is not proof of a leak.', 'A global dictionary keyed by every request ID grows indefinitely unless entries are evicted or removed.', 'Bounding retained state can change hit rate or diagnostics; choose a retention policy with an owner.', 'Repeat a bounded workload, compare live object growth, and verify that the suspected retaining path disappears after the fix.', 'Will calling the garbage collector fix it?', 'Not if the objects are still reachable. Remove or bound the retaining references.'),
    lesson('How do you make a Python service shutdown safely?', 'I stop admitting new work, allow bounded in-flight work to finish, cancel owned tasks that exceed the deadline, and close resources. Uncertain external operations retain their identity for recovery. Shutdown is a state transition with a deadline, not just a signal handler that exits.', 'A worker stops fetching messages, finishes or abandons its lease safely, and acknowledges only completed effects.', 'A longer drain window can improve completion but delays replacement; forced termination still needs replay-safe recovery.', 'Test shutdown during an idle period, database write, dependency timeout and duplicate delivery.', 'Should unfinished work be acknowledged?', 'Only if the durable workflow can prove the effect is complete; otherwise preserve safe retry or reconciliation.'),
  ],
  javascript: [
    lesson('What is a closure?', 'A closure is a function with access to the lexical bindings where it was created. It lets callbacks retain private state after the outer call returns. The bindings are live references to that environment, not automatically copied snapshots, so a long-lived callback can retain data or observe later changes.', 'Two counters created by separate factory calls keep separate state; two callbacks from one call can share it.', 'Closures support encapsulation but can retain a large object graph until listeners and references are released.', 'Test independent factory instances, later mutation and cleanup of registered callbacks.', 'Why can a loop callback see the wrong value?', 'Function-scoped var can share one binding across iterations; block-scoped let creates the intended per-iteration binding.'),
    lesson('Promise versus async/await?', 'An async function returns a promise; await pauses that function until the awaited result settles without blocking the whole JavaScript thread. Rejections still need a deliberate propagation or recovery policy. Independent operations are not concurrent merely because both lines contain await.', 'Awaiting A and then B serializes them; starting both and awaiting Promise.all can overlap independent work.', 'Promise.all rejects when one input rejects, but it does not automatically cancel the other operations.', 'Use controlled delayed promises to check ordering, rejection and cancellation behavior.', 'Does await make CPU work non-blocking?', 'No. Synchronous CPU work before an await still occupies the executing thread.'),
    lesson('How does the event loop work?', 'JavaScript executes a job to completion. The host schedules further work; promise reactions run as jobs/microtasks at host-defined checkpoints. Browser tasks, rendering and Node.js phases have different details. Long synchronous work prevents that thread from serving other callbacks even when the API is asynchronous.', 'A large synchronous JSON transformation can delay an otherwise ready timer and a user input handler.', 'Scheduling more microtasks is not a substitute for yielding fairly; an unbounded chain can starve other work.', 'Measure event-loop delay and interaction latency while injecting a large synchronous operation.', 'Is a zero-delay timer immediate?', 'No. It schedules eligible future work; earlier work, host policy and load affect when the callback runs.'),
    lesson('When should you memoize?', 'Memoization reuses a result for a defined input identity or key. I use it for repeated expensive work after measuring a bottleneck. The key must include every input that affects the answer, and retained entries need a lifetime or bound.', 'A price cache keyed only by product ID returns the wrong result when currency or tenant also affects price.', 'Caching trades recomputation for memory and invalidation complexity; cheap calculations may be faster without it.', 'Compare correct outputs and CPU/memory under repeated, changed and high-cardinality inputs.', 'Does memoization fix an incorrect function?', 'No. It can preserve and spread an incorrect result; establish correctness before adding reuse.'),
    lesson('How do you secure browser input?', 'Browser input is untrusted. I validate shape and size, encode output for the destination context, and enforce authorization at the server that owns the resource. A disabled button or client-side role check is a user-interface convenience, not a security boundary.', 'Changing a document ID in a request must still fail server-side when the authenticated user does not own that document.', 'Validation does not replace contextual output escaping, parameterized queries or authorization checks.', 'Test unauthorized IDs, injection-shaped strings, oversized input and safe error messages.', 'Can a browser store a secret API key safely?', 'A key shipped to a browser is available to its user; server credentials belong behind an authenticated server boundary.'),
    lesson('What is the difference between == and ===?', 'Strict equality compares without the coercion performed by loose equality. I generally use === for explicit contracts and handle intended conversions separately. Object equality compares references, not a recursive comparison of fields.', 'Two independently created objects with the same fields are not strictly equal; the same object reference is.', 'Neither operator implements domain value equality for arbitrary object graphs, and NaN has special equality behavior.', 'Test strings versus numbers, null versus undefined, NaN and distinct objects.', 'When is Object.is useful?', 'It distinguishes signed zero and considers NaN equal to itself; use it only when those semantics match the contract.'),
    lesson('How do const, let and var differ?', 'const prevents rebinding a binding, while let permits it; both have block scope. var has function or global scope and different initialization behavior. A const object can still be mutated unless its own data contract prevents that mutation.', 'const settings = {enabled:false} permits changing settings.enabled but not assigning a different object to settings.', 'Object.freeze is shallow; nested mutable objects still need a deliberate ownership policy.', 'Test rebinding, nested mutation and callbacks created inside a loop.', 'Does const make data immutable?', 'No. It constrains the binding rather than recursively freezing the referenced data.'),
    lesson('How does this depend on a call?', 'For an ordinary function, this depends on how the function is invoked. Arrow functions capture this from their surrounding lexical context. I avoid passing an unbound method when it relies on its receiver.', 'Passing an object method as a bare callback can lose its receiver; bind or a wrapper preserves the intended call.', 'Binding creates another function identity, which matters when later removing event listeners.', 'Invoke the same function as a method, a bare callback and a bound callback.', 'Can call change an arrow function’s this?', 'No. The arrow’s captured lexical this is not replaced by call, apply or bind.'),
    lesson('How do you copy an object safely?', 'Spread syntax and Object.assign make shallow copies of enumerable own properties, not deep independent object graphs. I define which state can be shared before selecting a copy mechanism. structuredClone supports many data types but not every function or host resource.', 'Copying a user object with a nested address leaves the address shared unless it is copied too.', 'JSON serialization loses or changes some values and is not a general deep-cloning protocol.', 'Test nested mutation, dates, undefined values, cycles and unsupported values for the selected mechanism.', 'Is serialization the same as cloning?', 'No. Serialization has a transport representation and can change identity or supported types.'),
    lesson('How should an API use AbortController?', 'An AbortController exposes a signal that cooperating APIs can observe. I pass one request lifetime through downstream work and classify abort separately from normal business failure. Aborting local waiting does not prove that the remote server rolled back a write.', 'A search UI aborts the prior fetch when a new query starts and ignores late results from the old request.', 'Cancellation support varies across APIs; cleanup and stale-response protection are still required.', 'Test a slow response, a response racing with abort, and cleanup when the view unmounts.', 'Should an aborted payment be retried with a new key?', 'No. Retain the original operation identity and reconcile its outcome before repeating an effect.'),
    lesson('How do you avoid stale asynchronous results?', 'I tie each result to the request or version that produced it. Cancellation reduces wasted work, while an identity check prevents an older result from replacing newer state even if cancellation loses a race. The UI must represent loading, failure and empty data separately.', 'Query B finishes before query A; only B’s result is allowed to update the current search results.', 'Ignoring late results protects the UI but does not stop server work; use both techniques where available.', 'Resolve controlled requests in reverse order and assert that the latest query owns the displayed result.', 'Why not check only whether the component is mounted?', 'A mounted component may have moved on to another query; request identity is more precise.'),
    lesson('How do you choose Map instead of an object?', 'Map provides explicit key/value collection operations and permits arbitrary values as keys. Plain objects are usually better for fixed record shapes. Object property keys and prototype behavior differ from Map keys, so I choose from the data contract rather than syntax preference.', 'A cache keyed by request objects can use Map without converting each key to a string.', 'Strong Map keys retain objects; WeakMap supports object-keyed associations without providing enumeration.', 'Test object identity, absent entries, iteration order and cleanup requirements.', 'Does a missing value always mean the key is absent?', 'No. A stored undefined value requires a separate has check to distinguish presence.'),
    lesson('What is event delegation?', 'A parent listener can handle events from descendants by inspecting the event target and the relevant ancestor. I distinguish the originating target from currentTarget, where the listener is registered, and ensure the matched element belongs to the intended container.', 'A list handles button clicks from newly added rows through one listener on the list.', 'Shadow DOM boundaries and non-bubbling events need their own event model; broad delegation can match unintended descendants.', 'Click nested icons, unrelated descendants and dynamically added rows, then verify the selected action.', 'Should stopPropagation be used everywhere?', 'No. It can break unrelated listeners; stop propagation only when the interaction contract requires it.'),
    lesson('How do you manage event listener cleanup?', 'A listener keeps its callback reachable, and that callback can retain its lexical environment. I give subscriptions an owner and remove or abort them when the owner ends. Removal must match the listener identity and relevant registration options.', 'A view that mounts repeatedly must not accumulate another window resize listener on each mount.', 'A global listener can simplify coordination but outlive the data it captures.', 'Mount and unmount repeatedly, fire the event and assert one active handler with no stale data.', 'Why does removing an inline arrow fail?', 'A newly created arrow is a different function object from the one originally registered.'),
    lesson('What does Array.sort guarantee about its comparator?', 'A comparator should consistently return a negative, zero or positive value for the intended ordering and should not mutate the compared data. The default ordering converts values to strings. I copy the array first when callers require the original order.', 'Without a numeric comparator, numbers such as 2 and 10 do not sort by numeric magnitude.', 'An inconsistent comparator can produce unreliable ordering; locale-sensitive text order needs an explicit locale policy.', 'Test equal keys, negative values, duplicates and whether the original array may change.', 'Why is returning only true or false wrong?', 'It does not express both ordering directions and equality consistently.'),
    lesson('How do modules affect a JavaScript application?', 'Modules define explicit imports and exports and are evaluated within the host’s module-loading rules. I keep side effects at deliberate entry points and avoid relying on import order to initialize hidden shared state. Browser and server module resolution are different deployment contracts.', 'A utility that reads browser window at module initialization cannot be imported safely during server rendering.', 'Circular imports can expose partially initialized dependencies; splitting ownership is often clearer than adding ordering tricks.', 'Test module import in the actual browser/server environments and inspect bundled dependencies.', 'Does exporting an object make it immutable?', 'No. Exported bindings and the mutability of the referenced object are separate concerns.'),
    lesson('How do you handle partial failure in concurrent promises?', 'I choose fail-fast behavior when every result is required and explicit per-result handling when partial results are acceptable. Promise.allSettled reports every settlement, but the application must still decide which failures are safe to expose as degraded output.', 'A product page can omit recommendations after a failure while treating a failed price lookup as an error.', 'Waiting for all results can delay a response unless each dependency has a deadline.', 'Inject one rejection and one slow promise; verify required versus optional data and resource cleanup.', 'Does Promise.all cancel remaining work?', 'No. It rejects its result but does not automatically cancel its input operations.'),
    lesson('Why is floating-point arithmetic risky for money?', 'JavaScript Number uses binary floating-point, so some decimal fractions cannot be represented exactly. I choose integer minor units within safe integer bounds or an explicit decimal representation, with a currency and rounding policy. Display formatting is not the same as correct arithmetic.', 'Splitting 100 cents across three recipients needs a documented rule for the one-cent remainder.', 'Integers still overflow the safe integer range, and not every currency uses two decimal minor digits.', 'Test totals, negative values, rounding boundaries, large values and conservation of allocated units.', 'Does toFixed solve the problem?', 'It formats a rounded string; it does not repair earlier arithmetic or define the business rounding policy.'),
    lesson('How can JSON parsing succeed but the request still be invalid?', 'Parsing establishes syntactic validity, not a trustworthy schema or authorized action. I validate required fields, types, bounds and unknown fields, then enforce ownership and business rules. I do not silently coerce untrusted values when doing so changes the contract.', 'The JSON value {minutes:"30"} is syntactically valid but violates an integer-duration contract.', 'Strict schemas reject accidental client drift; compatibility changes need deliberate versioning or additive rules.', 'Test wrong types, extra fields, missing IDs, out-of-range values and another tenant’s resource.', 'Can client-side validation replace this?', 'No. A caller can bypass the UI and send requests directly.'),
    lesson('What causes memory leaks in browser applications?', 'A leak occurs when unneeded state remains reachable, often through listeners, timers, caches or pending work. I compare retained memory after equivalent user flows and inspect retaining paths. A temporary allocation spike is not sufficient evidence of a leak.', 'A detached view can remain retained by a window listener whose closure captures the view’s data.', 'Aggressive cleanup can break shared owners, so subscriptions and caches need explicit lifetime contracts.', 'Repeat mount/use/unmount cycles and compare retained objects after collection in a controlled profile.', 'Will a weak reference fix every leak?', 'No. Weak reachability changes semantics and does not replace correcting the ownership path.'),
    lesson('How do you test time-dependent JavaScript code?', 'I inject a clock or use controlled timers for deterministic time rules, then test real integration timing separately. Expiry comparisons must specify inclusive or exclusive boundaries. I avoid making a unit test wait for wall-clock seconds just to prove a timestamp comparison.', 'An entry that expires at 100 is valid at 99 and expired at 100 under an exclusive-expiry contract.', 'Fake timers do not prove browser scheduling, network cancellation or production latency.', 'Test immediately before, at and after a deadline, plus cancellation and a late response.', 'Should every async test use a sleep?', 'No. Await an observable event or controlled promise; arbitrary delays make tests slow and flaky.'),
  ],
  aws: [
    lesson('How do you choose an AWS compute service?', 'I choose from workload duration, startup latency, isolation, networking and operational ownership. EC2 gives instance-level control; container services manage application packaging and scheduling; Lambda runs bounded invocations under its service contract. A managed service removes some work, not all capacity, security or failure planning.', 'A steady long-running worker and a bursty short event handler can justify different compute choices.', 'Compare full operating cost and dependency limits, not only the advertised compute billing unit.', 'Load-test cold and warm paths, shutdown, concurrency and dependency saturation using the actual service configuration.', 'Is serverless unlimited?', 'No. Quotas, concurrency and downstream resources still need explicit admission and scaling policies.'),
    lesson('How do you design for an AWS region failure?', 'I define recovery time and acceptable data loss before selecting a regional strategy. The design must recover data, traffic, identities, secrets and deployable artifacts together. Multiple availability zones address a different failure scope from multiple regions.', 'A warm standby with asynchronous data replication may recover service faster than rebuilding, while still allowing recent writes to be missing.', 'Active-active operation adds conflict, routing and operational complexity; backups alone do not provide immediate failover.', 'Rehearse loss of the primary region and measure recovery time, data gaps and duplicate operation handling.', 'Does DNS failover move every client immediately?', 'No. Cached DNS answers and existing connections can delay traffic movement.'),
    lesson('How should IAM be designed?', 'IAM defines which principals may perform actions on resources under conditions. I prefer scoped roles with temporary credentials, explicit resource ownership and least privilege. Authentication identifies a caller; authorization still checks whether this caller may access this tenant’s resource.', 'A workload role can read one application bucket prefix without receiving an account-wide static access key.', 'Overly broad policies simplify setup but enlarge impact. Narrow policies need tests for both intended access and explicit denial.', 'Exercise allowed and denied actions, cross-account boundaries and credential rotation; review audit events.', 'Is hiding an ARN a security boundary?', 'No. Knowledge of a resource identifier must not grant permission to access it.'),
    lesson('How do SQS consumers stay safe?', 'I assume messages can be delivered again and make the business effect idempotent. Visibility timeout controls temporary invisibility, not proof of successful processing. I delete a message only after the effect is durably complete, with bounded retry and an owned poison-message recovery path.', 'A consumer crash after committing an order but before deleting the message must not create the order again on redelivery.', 'Long visibility reduces concurrent duplicate processing but delays retry after worker failure.', 'Test duplicate delivery, visibility expiry, crash-after-commit and dead-letter redrive.', 'Does a FIFO queue remove the need for idempotency?', 'Its ordering and deduplication scope do not make arbitrary downstream effects atomic with message acknowledgement.'),
    lesson('How do you control AWS cost?', 'I model cost per useful outcome and include compute, storage, requests, transfer and operational effort. I tag ownership, observe real utilization, and define retention. A cheaper instance is not an improvement if it increases failures, recovery time or engineer effort.', 'A log-retention change can reduce storage cost, but must preserve the evidence required for incident investigation.', 'High availability and disaster recovery have costs; removing redundancy changes the user contract.', 'Compare bills and workload-normalized metrics before and after a bounded change; verify reliability separately.', 'Should all idle capacity be removed?', 'Not automatically. Some headroom is needed for bursts, failover, deployment overlap and recovery.'),
    lesson('Availability Zone versus Region?', 'A region is a geographic service area with availability zones designed as distinct failure domains. I distribute replicas and traffic according to the failures the product must survive. Placement alone does not ensure that applications, data and dependencies can fail over.', 'Two application instances in separate zones still share a single point of failure if both require one unavailable database.', 'Cross-zone and cross-region designs differ in latency, transfer cost and data-replication behavior.', 'Disable one zone’s path in a controlled exercise and verify remaining capacity and data access.', 'Does multi-AZ mean multi-region?', 'No. Regional outages require a separate regional recovery design.'),
    lesson('How should an application use S3 object storage?', 'S3 stores objects identified by bucket and key. I design object ownership, access policy, encryption, retention and versioning explicitly. Object storage is not a general replacement for a database transaction that atomically changes several related records.', 'An upload workflow records pending metadata, uploads the object, then marks it available; orphan cleanup repairs partial failures.', 'Large objects and lifecycle policies can reduce some storage costs while changing retrieval and deletion behavior.', 'Test denied access, overwritten keys, failed metadata updates and lifecycle/versioning requirements.', 'Does deleting the current object prove all versions are gone?', 'Not when versioning or retention policies preserve older versions; deletion requirements must cover those states.'),
    lesson('How do you choose RDS versus DynamoDB?', 'I compare access patterns, transactions, indexes, consistency and operating model. RDS exposes a relational database’s joins and transaction capabilities; DynamoDB requires deliberate key/access-pattern design. Neither option eliminates hot keys or the need to understand limits.', 'An order workflow with complex relational queries differs from a key-addressed session lookup with predictable access patterns.', 'A design that fits simple primary-key reads may need extra indexes or derived data for new query patterns.', 'Test representative queries, skew, transaction conflicts and recovery on the chosen engine/service.', 'Is NoSQL always faster?', 'No. Performance depends on the operation, key distribution, data size, consistency and provisioned resources.'),
    lesson('What does DynamoDB read consistency mean?', 'I choose read consistency per supported operation and state the user-visible freshness promise. A strongly consistent read and a transaction solve different problems. Replication across regions and reads through different index types have their own contracts, which must be checked for the chosen configuration.', 'After changing account preferences, a read-your-writes path should not accidentally read a stale derived view.', 'Stronger read requirements can change cost, latency and available operations.', 'Test immediate reads after writes through each actual table/index/region path.', 'Does a strong read make two writes atomic?', 'No. Atomic multi-item changes require an applicable transaction or a redesigned ownership boundary.'),
    lesson('How do load balancer health checks affect availability?', 'A load balancer routes eligible traffic to targets that meet configured health criteria. I make those checks reflect serving capability without turning every shared dependency incident into a restart or removal storm. Application readiness and process liveness are different questions.', 'A target should stop receiving new checkout traffic before shutdown while existing requests drain within a bound.', 'Aggressive thresholds detect failure quickly but can flap; slow thresholds prolong routing to unhealthy targets.', 'Test readiness changes, graceful drain, partial dependency failure and insufficient remaining capacity.', 'Does a healthy target guarantee a successful request?', 'No. Health checks sample a limited contract and cannot prove every operation’s correctness.'),
    lesson('How should Auto Scaling be verified?', 'Auto Scaling changes capacity according to configured policies and available resources. I select a signal tied to the bottleneck, account for startup delay, and retain an overload policy while capacity catches up. Scaling application instances cannot remove a saturated database lock.', 'A traffic burst may arrive before new instances are ready; bounded admission protects the dependency during the gap.', 'Fast scale-in saves cost but can interrupt work or oscillate without appropriate stabilization.', 'Rehearse bursts and scale-in while measuring useful throughput, queue age and drained work.', 'Is CPU always the right scaling signal?', 'No. Queue age, request concurrency or another saturation signal may better represent the workload.'),
    lesson('How do SNS, SQS and EventBridge differ?', 'SNS supports publish/subscribe fanout; SQS provides queues for consuming work; EventBridge routes events under configured matching and delivery rules. I choose by ownership, routing, replay and failure requirements rather than calling all three interchangeable messaging.', 'An event can fan out to separate queues so billing and notifications have independent retry and backlog behavior.', 'Fanout multiplies deliveries and operational state; each consumer still owns idempotency and poison-message handling.', 'Test routing filters, duplicate delivery, downstream outage and dead-letter recovery.', 'Can publication replace a database transaction?', 'No. Use an outbox or another explicit atomicity/recovery mechanism across the database/message boundary.'),
    lesson('What belongs inside a VPC security boundary?', 'A VPC supplies a configurable network environment, but network placement alone is not authorization. I define routing, security groups, endpoint access and identity together. Private addressing does not prove that a caller may access every record behind an endpoint.', 'A private service still checks tenant ownership after authenticating a workload request.', 'Restricting egress reduces exposure but requires deliberate access to package, telemetry and dependency endpoints.', 'Test allowed and denied network paths separately from application authorization.', 'Is a security group a substitute for IAM?', 'No. Network reachability and permission to perform a service action are distinct controls.'),
    lesson('How do you protect secrets in AWS applications?', 'I use workload identity to retrieve scoped secrets and avoid embedding credentials in images, source or logs. Rotation includes consumers, cached credentials and new connections. Encryption at rest does not protect a secret printed into application logs.', 'A database credential rotates with a controlled overlap while the application proves new connections succeed.', 'Caching secrets improves availability but delays rotation unless refresh and expiry behavior are explicit.', 'Test rotation, denied retrieval, stale credentials and redaction in errors and traces.', 'Should the frontend receive a server secret?', 'No. A browser user can inspect delivered data; keep server credentials behind the authorized server boundary.'),
    lesson('What should a CloudWatch alarm measure?', 'I alarm on an actionable user-impacting condition and attach an owner and response path. Metrics diagnose trends; logs and traces supply context. Thresholds need workload windows and sufficient event counts, especially for low-traffic services.', 'A growing oldest-message age can reveal a stuck worker even while host CPU remains low.', 'Many infrastructure alerts create noise if they do not identify affected outcomes or a useful action.', 'Inject one controlled failure and verify detection, routing, runbook usefulness and recovery.', 'Should every error page an engineer?', 'No. Severity, sustained impact, error-budget policy and automatic recovery determine the response.'),
    lesson('How do retries interact with Lambda?', 'An invocation may be retried depending on its event source and invocation mode. I define durable operation identity and idempotent effects, then check the source-specific retry, batching and failure policy. A successful handler return must correspond to the intended durable outcome.', 'A retried event that already updated an invoice should return the prior effect instead of applying the amount again.', 'Long work and downstream saturation may require queues, admission limits and a different compute model.', 'Test repeated events, timeout-after-effect and partial batch failure with the actual source settings.', 'Are all Lambda retry policies identical?', 'No. Synchronous, asynchronous and event-source integrations have different contracts.'),
    lesson('How do you define backup success?', 'A backup is useful only if the required state can be restored within the agreed recovery objectives. I include data, schema, encryption keys, configuration and application compatibility. Replication alone is not a substitute for recovery from accidental deletion or corruption.', 'A restore drill into an isolated environment verifies record counts, integrity and application reads before declaring the backup usable.', 'Short retention reduces cost but narrows the recovery window; cross-region copies add dependencies and access requirements.', 'Measure restore duration and recovered data age through a realistic recovery exercise.', 'Does a successful backup job prove recovery?', 'No. It proves that job’s completion, not that restoration and application reconciliation succeed.'),
    lesson('How should a CDN cache be keyed?', 'A cache key must include every request dimension that changes the response and is safe to share. I distinguish public content from personalized or tenant-specific data and define invalidation and TTL. A fast cache hit with another user’s data is a correctness and isolation failure.', 'An authenticated account response should not be shared merely because the URL path matches.', 'More key dimensions improve isolation but can lower hit rate and increase origin traffic.', 'Test two users/tenants, authorization changes, expiry and invalidation races.', 'Is a short TTL enough for private data?', 'No. A brief cross-user disclosure is still a disclosure; access and cache partitioning must be correct.'),
    lesson('What makes an AWS deployment rollback-safe?', 'I deploy an immutable artifact gradually and define failure signals before rollout. Database and event changes must remain compatible while old and new versions coexist. Switching application traffic back cannot undo an incompatible schema deletion or external side effect.', 'Add a nullable column, deploy compatible readers/writers, backfill and verify, then remove old behavior later.', 'Keeping compatibility paths temporarily increases complexity but preserves recovery options.', 'Test mixed-version traffic, failed backfill, canary abort and rollback using the same artifact/configuration contracts.', 'Is reverting a container tag sufficient?', 'Only if data, configuration and external contracts remain compatible with the previous version.'),
    lesson('How do you manage AWS quotas and dependency limits?', 'I inventory finite service quotas and downstream capacities, then bound admitted work below a tested safe operating level. A queue shifts work in time but still needs a backlog and retention policy. Quota increases do not fix expensive operations or skew.', 'A worker concurrency limit prevents a sudden message burst from opening more database connections than the database can serve.', 'Extra headroom costs money, while operating at the limit leaves little capacity for retries and failover.', 'Test bursts, throttling, retries and catch-up after outage; monitor utilization and oldest work age.', 'Should throttling always trigger an immediate retry?', 'No. Backoff, jitter and an overall deadline prevent retries from amplifying overload.'),
  ],
};

export const STACK_GUIDE_LESSONS = {
  react: [
    lesson('When should I use an effect instead of computing during render?', 'An effect synchronizes a component with an external system after a commit. Pure derived values belong in render; a user-triggered mutation usually belongs in its event handler. I include every reactive dependency and return cleanup for subscriptions, so changing inputs does not leave an old connection alive.', 'A chat room effect disconnects room A before subscribing to room B. Filtering an in-memory list needs no effect.', 'Unnecessary effects introduce extra updates and stale-state races. Strict Mode’s development checks expose missing cleanup rather than promising one execution.', 'Mount, change the room and unmount; assert one active subscription and ignored late responses.', 'Can I omit dependencies to stop reruns?', 'No. Restructure the effect or stabilize the right dependency; suppressing a dependency hides a stale-closure bug.'),
    lesson('Where should shared state live?', 'I place state in the nearest common owner that must coordinate it and pass data and callbacks explicitly. A controlled child receives its current value rather than maintaining a competing copy. Server data, URL state and transient field input can have different owners and lifetimes.', 'Two temperature fields share one canonical value and derive their displays, avoiding two inconsistent stored temperatures.', 'Lifting every keypress to the application root increases coupling and render work; keep unrelated transient state local.', 'Test editing either child, reset behavior and navigation; verify there is one source of truth.', 'Does context solve every ownership problem?', 'No. Context transports a value; it does not choose a correct state model or eliminate update costs.'),
    lesson('When do useMemo and useCallback help?', 'useMemo caches a calculation and useCallback caches a function identity between renders when their dependencies match. I use them after measuring an expensive calculation or a meaningful memoized-child boundary. They are performance tools, not a way to make impure rendering correct.', 'A measured expensive filter can be memoized by the actual data and filter inputs; an omitted filter dependency would return stale results.', 'Memoization retains values and adds comparison/maintenance work. Cheap calculations or unstable inputs may not benefit.', 'Profile before and after, change every dependency, and confirm results remain correct without the optimization.', 'Should correctness depend on the cache?', 'No. The calculation must remain correct when React recomputes it.'),
  ],
  nodejs: [
    lesson('Why can an async Node.js endpoint still block other requests?', 'async marks a promise-returning function, not a separate execution thread. Synchronous parsing or computation still occupies the event-loop thread. I bound input, stream suitable work and isolate expensive CPU tasks in a controlled worker facility rather than assuming more promises create CPU capacity.', 'A large synchronous report calculation can delay a tiny health request even if the report handler is declared async.', 'Worker isolation has transfer and coordination cost; moving work also requires limits on queued jobs.', 'Measure event-loop delay and small-request latency during a representative large request.', 'Does a timer fix CPU blocking?', 'A timer defers when work starts; the synchronous work still blocks while it runs.'),
    lesson('What does stream backpressure protect?', 'Backpressure prevents a producer from outrunning a consumer indefinitely. With a writable stream I respect a false write result and the drain signal, or use pipeline for coordinated flow and error cleanup. I bound individual chunks as well as buffered work.', 'A file download to a slow client should not first read the entire file into application memory.', 'Streaming lowers retained data but keeps resources open longer; a broken client needs cancellation and cleanup.', 'Use a slow consumer, force an intermediate error and disconnect the client; verify bounded buffers and closed streams.', 'Does highWaterMark impose an absolute memory cap?', 'No. It is a buffering threshold, not a complete process-memory guarantee.'),
    lesson('How should a Node.js API propagate cancellation and errors?', 'I give request work an explicit lifetime, pass an AbortSignal to cooperating dependencies and close owned resources on completion or cancellation. Errors are classified and mapped once at the boundary. A client disconnect stops local work where supported, but does not prove a remote write was cancelled.', 'An abandoned search aborts its fetch and ignores a racing response; an abandoned payment keeps its operation key for reconciliation.', 'Cancellation is cooperative, so unsupported libraries need independent timeouts and admission controls.', 'Test caller abort, timeout, dependency rejection and cleanup failure without leaking unhandled rejections.', 'Should cancellation be returned as ordinary success?', 'No. Preserve the operation’s actual outcome and avoid claiming a side effect completed or rolled back without evidence.'),
  ],
  go: [
    lesson('How do you give a goroutine a safe lifetime?', 'I identify who starts the goroutine, how cancellation reaches it and who waits for completion. A context carries cancellation and deadlines across cooperating calls; it does not kill a goroutine automatically. Every blocking send, receive and dependency call needs an exit policy.', 'A request fanout cancels sibling work after the request ends and waits for owned workers to release resources.', 'Detached background goroutines can outlive request state; bounded service workers need a separate service lifetime.', 'Cancel during blocked sends and dependency waits, and check that goroutine counts return to baseline.', 'Does calling cancel wait for work to stop?', 'No. The owner still needs a completion/join mechanism when shutdown requires it.'),
    lesson('Channels or mutexes?', 'I use channels when passing work or ownership makes the workflow clearer and mutexes when protecting a shared invariant is simpler. A channel does not make unrelated shared memory race-free. The synchronization design must cover all accesses to the protected state.', 'A bounded worker queue transfers jobs; a small shared counter can be protected by a mutex or an appropriate atomic operation.', 'Unbuffered channels coordinate handoff, while buffered channels allow bounded decoupling but can hide waiting and shutdown complexity.', 'Run the race detector and test full queues, cancellation and concurrent state updates.', 'Who should close a channel?', 'Usually the sender that owns completion, after proving no more sends can occur.'),
    lesson('How do you avoid a Go worker-pool leak?', 'I bound both workers and queued jobs, make producers observe cancellation, and define whether shutdown drains or rejects remaining work. Workers select on the relevant cancellation signal while waiting. Results need a consumer or a cancellation path so workers cannot block forever sending them.', 'A request that times out must not leave workers permanently blocked on an abandoned result channel.', 'Draining improves completion but can exceed shutdown budgets; rejecting requires replay-safe ownership of unfinished work.', 'Test zero work, full queues, cancelled producers and consumers, and shutdown with a blocked dependency.', 'Is a buffered results channel enough?', 'Only for the bounded workload it can hold; it is not a general substitute for lifetime ownership.'),
  ],
  rust: [
    lesson('How do ownership and borrowing prevent invalid access?', 'An owned value has a responsible owner; borrowing lets code access it without taking ownership. Safe Rust checks that references remain valid and that conflicting mutable/shared borrows do not overlap. This prevents a class of memory-safety bugs but does not prove business correctness or deadlock freedom.', 'A function taking &str can inspect a caller’s String without consuming it; a mutation requires the appropriate exclusive access.', 'Cloning can simplify ownership but copies data; borrowing can make lifetimes and API boundaries more demanding.', 'Compile valid and intentionally conflicting borrow examples, then test the domain behavior separately.', 'Does a lifetime annotation extend an object’s lifetime?', 'No. It describes relationships the compiler must verify; it does not keep a destroyed value alive.'),
    lesson('When should I use Result instead of panic?', 'Result represents an expected recoverable failure in the function contract. I propagate or translate it at a boundary and preserve useful context without exposing secrets. A panic indicates an unrecoverable assumption failure for that path, not normal user-input validation.', 'Parsing an uploaded count returns an error for malformed text instead of panicking and aborting request work.', 'Many tiny error types can burden callers, while one opaque string loses structured recovery information.', 'Test successful input, malformed input and cause-preserving boundary conversion.', 'Does the question-mark operator handle an error?', 'It propagates a compatible error to the caller; recovery still belongs somewhere in the call chain.'),
    lesson('How does Arc<Mutex<T>> affect concurrency?', 'Arc shares ownership through reference counting, while Mutex serializes access to protected state. The combination does not remove contention or make multi-resource workflows atomic. I keep critical sections small and avoid holding a synchronous lock across unrelated blocking work.', 'Several workers can share one bounded registry, but every access to its invariant must follow the same synchronization contract.', 'Message passing or confinement may simplify ownership; shared locks can be appropriate for a small coherent state transition.', 'Test concurrent updates, failure inside the critical section and lock-order interactions.', 'Does Arc make T thread-safe?', 'No. It provides shared ownership; the type’s Send/Sync and synchronization requirements remain relevant.'),
  ],
  docker: [
    lesson('Image versus container?', 'An image describes packaged filesystem layers and runtime configuration; a container is a running or stopped instance with its own writable layer and process state. I build an immutable application artifact and supply environment-specific configuration at runtime. Persistent business data needs an explicit storage and backup contract.', 'Replacing a container must not lose an order database that was accidentally stored only in its writable layer.', 'A smaller image can reduce transfer and exposure, but it still needs required runtime libraries and a patching process.', 'Run the exact image digest, recreate the container, and verify configuration and persistent-data behavior.', 'Does containerization reproduce the entire host?', 'No. Kernel, architecture, resource limits, network and mounted data remain part of the runtime contract.'),
    lesson('Why use a multi-stage build?', 'A multi-stage Docker build separates compilation/tooling from the final runtime filesystem. I copy only the required artifact and runtime dependencies into the final stage. I also pin and verify base artifacts and avoid leaving secrets in build arguments or copied layers.', 'A Java build stage can contain Maven while the runtime stage contains the application and its supported runtime.', 'Removing tools reduces size but can make diagnosis harder; plan supported diagnostics rather than silently shipping an unusable image.', 'Inspect the final image, run startup tests and verify that build credentials and unused tooling are absent.', 'Does deleting a secret in a later layer remove it?', 'It may remain in earlier layers. Use supported build-secret mechanisms and avoid committing it into a layer.'),
    lesson('How should a container shut down?', 'The application should receive termination, stop new admission and finish or safely abandon owned work within a finite grace period. I use an appropriate entrypoint so signals reach the intended process. A health check does not replace shutdown coordination or durable retry semantics.', 'A worker stops fetching jobs, releases or completes its current lease, and exits before the platform forces termination.', 'A long grace period improves draining but delays rollout; a short one requires robust recovery of unfinished effects.', 'Send termination during idle and busy operation and verify signals, exit status, cleanup and replay behavior.', 'Does EXPOSE publish a port?', 'No. It documents a port; actual network publication and routing are separate runtime configuration.'),
  ],
  mongodb: [
    lesson('When should MongoDB data be embedded instead of referenced?', 'I start from reads, writes, growth and atomicity. Embedding keeps bounded related data together and permits a single-document update boundary. References avoid unbounded duplication or growth but require additional reads or coordination. A document database still needs a deliberate schema and validation policy.', 'An order can embed a snapshot of purchased item names, while an unbounded customer activity history belongs in a separate collection.', 'Duplicated snapshots preserve historical meaning but do not automatically follow later source updates.', 'Test realistic document growth, update frequency and the exact query paths.', 'Is embedding every relationship simpler?', 'Only until unbounded arrays, duplication or independently updated entities make the document boundary inappropriate.'),
    lesson('How do you choose a MongoDB index?', 'I design indexes from actual filters, sorting and expected selectivity, then inspect the query plan. Compound key order must support the access pattern. Each index adds write maintenance and storage, so indexing every field is not a free performance improvement.', 'A tenant-scoped feed needs an access path that combines tenant filtering with its deterministic time/ID ordering.', 'An index useful for one query may not help another; multikey and covered-query behavior have additional constraints.', 'Use explain with representative data and compare examined documents, examined keys and latency alongside write cost.', 'Does an index force the optimizer to use it?', 'No. The optimizer can choose another plan; verify the selected plan instead of assuming index presence proves use.'),
    lesson('What consistency boundary does a MongoDB update provide?', 'An individual document write is atomic, while multi-document workflows need their own transaction or recovery design. Read and write concerns describe additional visibility and durability choices. I state the required invariant before choosing those settings and test the deployed topology.', 'Two updates to different account documents are not a balanced transfer merely because each update is atomic on its own.', 'A transaction can protect a wider invariant but adds coordination and operational cost; a better document boundary may be simpler.', 'Test concurrent updates, ambiguous acknowledgements, failover and idempotent retry with the selected concerns.', 'Does a timeout mean no write occurred?', 'No. The caller may have lost the acknowledgement; retain operation identity and reconcile before repeating an effect.'),
  ],
};

for (const [stack, entries] of Object.entries(PUBLIC_INTERVIEW_LESSONS)) {
  entries.forEach((entry, index) => Object.assign(entry, { id: `${stack}-${index + 1}`, sources: INTERVIEW_LESSON_SOURCES[stack] }));
}
for (const [stack, entries] of Object.entries(STACK_GUIDE_LESSONS)) {
  entries.forEach((entry, index) => Object.assign(entry, { id: `${stack}-${index + 1}`, sources: INTERVIEW_LESSON_SOURCES[stack] }));
}
